 const add=(id,label,thumb,position,axis,travel,kind)=>{const c=host.add(new ServiceSlide({id,label,mesh:thumb,position,axis,travel,latching:true,longPressMs:0,meta:{role:'visual-control',pointerAccessible:open,mechanism:'retained-slide',positions:['rest','shifted'],detentsMm:[0,travel],travelSource:'Own U160 board photographs;installed throw and package dimensions are inferred',scope:kind+' physical actuator and input intent only. Closed front cover blocks pointer access;frontCover:false exposes actual board. No address mapping,power routing,motor,voltage,current,PWM,electrical or firmware behavior'}}));if(!open)c.cap.traverse(o=>{delete o.userData.component;});return c;};
 const source=add('source','S1 · DCDC-5V / HV-12V physical slide',cap,spec.selector.position,spec.selector.axis,spec.selector.travelMm,'S1 power-source selector');source.meta.sourceLabels=spec.selector.sourceLabels;
