function fixing(host){const s=new THREE.Shape();s.absarc(0,0,1.5,0,tau,false);const h=new THREE.Path();for(let i=0;i<6;i++){const a=i*tau/6;if(i)h.lineTo(.6*Math.cos(a),.6*Math.sin(a));else h.moveTo(.6*Math.cos(a),.6*Math.sin(a));}h.closePath();s.holes.push(h);const tin=materials.metal(0xb0baac,{roughness:.45}),head=solid(host.body,s,.42,spec.screw.position,tin,'Original U160 actual fixed rear retaining screw annular hex head'),blind=mesh(host.body,new THREE.CylinderGeometry(.6,.6,.12,6).rotateX(Math.PI/2),materials.metal(0x5c665b),[0,-16,-3.47],'Original U160 actual hex-recess blind floor'),shank=mesh(host.body,new THREE.CylinderGeometry(.6,.6,4.8,32).rotateX(Math.PI/2),tin,[0,-16,-.9],'Original U160 fixed rear retaining shank');return{head,blind,shank};}
export function buildHBridge(host,{frontCover=true,terminalPlug=false}={}){for(const[k,v]of Object.entries({frontCover,terminalPlug}))if(typeof v!=='boolean')throw new TypeError(k+' must be boolean');const selected=frontCover?data:data.filter(p=>p.assemblySubset!=='front'),parts=addCadParts(host,selected,{shell:materials.plastic(0xe7e9e2,{roughness:.86})}),pcb=circuit(host),input=grove(host),output=terminal(host),actuators=controls(host,!frontCover),screw=frontCover?fixing(host):null,labels={};for(const face of frontCover?['front','back']:['back']){const v=spec.labels[face],p=slab(host.body,...v.size,face==='front'?.05:.04,.4,v.position,materials.plastic(0xe8ebe5,{roughness:.89}),[],.005);p.name='Original U160 real '+face+' adhesive film';p.userData={role:'physical-label-substrate',face};labels[face]=p;}host.hbridgeAssembly={parts,pcb,input,output,controls:actuators,screw,labels};host.unitStickers=addStickers(host,{frontCover});if(terminalPlug)output.port.attach(new TerminalPlug());}
